/**
 * Copies the MediaPipe Tasks Vision WASM runtime out of node_modules and into
 * public/mediapipe/wasm so the browser can fetch it from our own origin.
 *
 * We self-host rather than pointing FilesetResolver at a CDN for three reasons:
 *   1. Privacy — no third-party request is made while a camera is open.
 *   2. The runtime version can never drift away from the installed package.
 *   3. It keeps working offline, which matters for clinic and school networks.
 *
 * The files are ~34 MB, so they are gitignored and regenerated by predev/prebuild
 * instead of being committed.
 */
import { cp, mkdir, readdir, stat } from "node:fs/promises";
import { createRequire } from "node:module";
import path from "node:path";

const require = createRequire(import.meta.url);

const packageEntry = require.resolve("@mediapipe/tasks-vision");
const sourceDir = path.join(path.dirname(packageEntry), "wasm");
const targetDir = path.join(process.cwd(), "public", "mediapipe", "wasm");

await stat(sourceDir).catch(() => {
  throw new Error(
    `Could not find MediaPipe WASM assets at ${sourceDir}. Run \`npm install\` first.`,
  );
});

await mkdir(targetDir, { recursive: true });
await cp(sourceDir, targetDir, { recursive: true });

const copied = await readdir(targetDir);
console.log(
  `[mediapipe] copied ${copied.length} runtime files to public/mediapipe/wasm`,
);
